import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const _=JSON.parse('{"title":"Ring 3 与系统调用面","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/syscall-ring3.md","filePath":"zh/arch/syscall-ring3.md"}'),r={name:"zh/arch/syscall-ring3.md"};function s(a,t,i,l,n,S){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="ring-3-与系统调用面" tabindex="-1">Ring 3 与系统调用面 <a class="header-anchor" href="#ring-3-与系统调用面" aria-label="Permalink to &quot;Ring 3 与系统调用面&quot;">​</a></h1><p>用户代码如何触达内核：一条指令（<code>int 0x80</code>）、54 个系统调用号、 一扇 5 参数的服务之门（<code>SYS_L1SVC</code>），以及让 208 个服务操作返回 文本的输出捕获机制。ABI 契约镜像于 <code>ocos/interface/</code> （<a href="./private-headers.html">private-headers.md</a>）；进程/ELF 一侧位于 <code>ocos/kernel/core_usermode.c</code>（1518 行）。</p><h2 id="入口路径" tabindex="-1">入口路径 <a class="header-anchor" href="#入口路径" aria-label="Permalink to &quot;入口路径&quot;">​</a></h2><p>Ring 3 执行 <code>int 0x80</code>。向量 128 的 IDT 门携带标志 <strong>0xEE （DPL=3）</strong>，因此该指令在用户态合法（选择子 0x18，中断门——处理器 期间中断关闭）。链条：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int 0x80</span></span>
<span class="line"><span>  -&gt; arch_isr_stub_128        (pushes fake error code + vector number)</span></span>
<span class="line"><span>  -&gt; arch_isr_common          (pushes 15 GPRs, cld, 16-byte align)</span></span>
<span class="line"><span>  -&gt; arch_isr_dispatch        (frame = 22 u64s, arch_irq_frame_t)</span></span>
<span class="line"><span>  -&gt; core_syscall_dispatch((u64*)frame)     [core_usermode.c]</span></span></code></pre></div><p><strong>ABI</strong>：<code>rax</code> = 系统调用号；参数在 <code>rdi, rsi, rdx, r10</code>（第 4 参） 与 <strong><code>r8</code>（第 5 参）</strong>；返回值在 <code>rax</code>；未知或未注册的编号返回 -1。 第 5 参数槽位恰为一个系统调用所用——<code>SYS_L1SVC</code> 的 <code>cap</code>——并在 处理器运行前暂存进 <code>g_syscall_arg5</code>（帧槽 <code>regs[7]</code>；<code>regs[5]</code> 是 r10）。没有 <code>sysenter</code>/<code>syscall</code> 指令的快速路径——只有 int 0x80——也没有按任务的嵌套：系统调用从不在一个任务内递归。信号 投递发生在处理器返回之后、<code>iretq</code> 之前。</p><p>注册：<code>core_syscall_register(num, handler)</code> 注册进 <code>g_syscalls[256]</code>； <code>usermode_init()</code> 播种 0/1/2，随后调用 <code>core_syscall_wp08a_init()</code> + <code>core_syscall_wp08fix1_init()</code> + <code>core_syscall_l1svc_init()</code>（函数体位于 <code>ocos/services/sysapi/src/svc_sysapi_syscall.c</code>）。</p><h2 id="完整系统调用表-54-个编号" tabindex="-1">完整系统调用表（54 个编号） <a class="header-anchor" href="#完整系统调用表-54-个编号" aria-label="Permalink to &quot;完整系统调用表（54 个编号）&quot;">​</a></h2><p>来自 <code>ocos/services/sysapi/interface/svc_sysapi_syscall.h</code>：</p><table tabindex="0"><thead><tr><th>#</th><th>名称</th><th>用途</th></tr></thead><tbody><tr><td>0</td><td><code>SYS_EXIT</code></td><td>遗留退出（现在也运行统一收割器）</td></tr><tr><td>1</td><td><code>SYS_WRITE</code></td><td>控制台写，带按页映射检查</td></tr><tr><td>2</td><td><code>SYS_WRITE_AND_EXIT</code></td><td>写后退出</td></tr><tr><td>3</td><td><code>SYS_OPEN</code></td><td>(path, flags)</td></tr><tr><td>4</td><td><code>SYS_CLOSE</code></td><td>(fd)</td></tr><tr><td>5</td><td><code>SYS_STAT</code></td><td>(path, struct ush_stat*)</td></tr><tr><td>6</td><td><code>SYS_READDIR</code></td><td>(path, idx, buf)</td></tr><tr><td>7</td><td><code>SYS_MKDIR</code></td><td>(path)</td></tr><tr><td>8</td><td><code>SYS_RMDIR</code></td><td>(path)</td></tr><tr><td>9</td><td><code>SYS_UNLINK</code></td><td>(path)</td></tr><tr><td>10</td><td><code>SYS_FORK</code></td><td>完整帧保存 + 地址空间拷贝 + fork 子路径</td></tr><tr><td>11</td><td><code>SYS_EXECVE</code></td><td>(name/argv)——gzip 注册表查找 + ELF 装载</td></tr><tr><td>12</td><td><code>SYS_WAIT4</code></td><td>(pid, &amp;status)</td></tr><tr><td>13</td><td><code>SYS_KILL</code></td><td>(pid, sig)——受守护进程拒绝一切信号</td></tr><tr><td>14</td><td><code>SYS_GETPID</code></td><td></td></tr><tr><td>15</td><td><code>SYS_GETPPID</code></td><td></td></tr><tr><td>16</td><td><code>SYS_EXIT2</code></td><td>现代退出（crt0 使用）</td></tr><tr><td>20</td><td><code>SYS_PIPE</code></td><td>(int pipefd[2])</td></tr><tr><td>30</td><td><code>SYS_MMAP</code></td><td>每进程匿名递增分配器，位于 [0x3C000000, 0x3FFF0000)</td></tr><tr><td>31</td><td><code>SYS_MUNMAP</code></td><td>(addr, len)</td></tr><tr><td>32</td><td><code>SYS_MPROTECT</code></td><td>(addr, len, prot)——为 ld.so 提供 W^X</td></tr><tr><td>33</td><td><code>SYS_BRK</code></td><td>(addr)</td></tr><tr><td>40</td><td><code>SYS_SIGNAL</code></td><td>(sig, handler)</td></tr><tr><td>41</td><td><code>SYS_SIGACTION</code></td><td>(sig, act)</td></tr><tr><td>42</td><td><code>SYS_SIGRETURN</code></td><td>恢复保存的 22-u64 信号帧</td></tr><tr><td>50</td><td><code>SYS_DUP</code></td><td>(fd)</td></tr><tr><td>51</td><td><code>SYS_DUP2</code></td><td>(oldfd, newfd)</td></tr><tr><td>60</td><td><code>SYS_CHDIR</code></td><td>每进程 cwd</td></tr><tr><td>61</td><td><code>SYS_GETCWD</code></td><td></td></tr><tr><td>62</td><td><code>SYS_IOCTL</code></td><td></td></tr><tr><td>70</td><td><code>SYS_READ</code></td><td>(fd, buf, len)</td></tr><tr><td>72</td><td><code>SYS_WRITE2</code></td><td>fd 感知的写（管道/重定向）</td></tr><tr><td>73</td><td><code>SYS_READLINE</code></td><td>内核行编辑器</td></tr><tr><td>74</td><td><code>SYS_GETCH</code></td><td>原始按键，无回显，非阻塞轮询</td></tr><tr><td>75</td><td><code>SYS_UPTIME</code></td><td>自引导以来的毫秒数</td></tr><tr><td>76</td><td><code>SYS_MEMINFO</code></td><td>从 PMM 填 3 个 u64（总计/已用/空闲）</td></tr><tr><td>80</td><td><code>SYS_SELECT</code></td><td></td></tr><tr><td>81</td><td><code>SYS_POLL</code></td><td></td></tr><tr><td>90</td><td><code>SYS_MAP_SOLIB</code></td><td>dlopen 内核侧（WP-08b）</td></tr><tr><td>96</td><td><code>SYS_SYMLINK</code></td><td>(target, linkpath)</td></tr><tr><td>97</td><td><code>SYS_READLINK</code></td><td></td></tr><tr><td>98</td><td><code>SYS_LINK</code></td><td>硬链接</td></tr><tr><td>99</td><td><code>SYS_CHMOD</code></td><td></td></tr><tr><td>100</td><td><code>SYS_CHOWN</code></td><td></td></tr><tr><td>101</td><td><code>SYS_NETCMD</code></td><td>(op, arg, out, cap)；ops：IFCONFIG=1 PING=2 NETSTAT=3 WGET=4</td></tr><tr><td>102</td><td><code>SYS_PS</code></td><td>(buf, cap) -&gt; struct ush_ps_entry[]</td></tr><tr><td>103</td><td><code>SYS_SOCKET</code></td><td>(type SOCK_TCP=1/SOCK_UDP=2)</td></tr><tr><td>104</td><td><code>SYS_NETBIND</code></td><td></td></tr><tr><td>105</td><td><code>SYS_NETCONNECT</code></td><td></td></tr><tr><td>106</td><td><code>SYS_NETACCEPT</code></td><td></td></tr><tr><td>107</td><td><code>SYS_NETSEND</code></td><td></td></tr><tr><td>108</td><td><code>SYS_NETRECV</code></td><td></td></tr><tr><td>109</td><td><code>SYS_NETCLOSE</code></td><td></td></tr><tr><td>110</td><td><code>SYS_L1SVC</code></td><td>(cat, op, arg, out, cap)——服务之门</td></tr></tbody></table><p>套接字系统调用取的是<strong>网络套接字 id，不是进程 fd</strong>——它们不参与 dup/select/poll/fork（文档见 <code>services/ipc</code>）；NETCMD 桥让历史上的 ush 内建命令（ifconfig/ping/netstat/wget）留在同一套被捕获的函数 体上。</p><h2 id="sys-l1svc——唯一的服务之门" tabindex="-1">SYS_L1SVC——唯一的服务之门 <a class="header-anchor" href="#sys-l1svc——唯一的服务之门" aria-label="Permalink to &quot;SYS_L1SVC——唯一的服务之门&quot;">​</a></h2><p><code>sys_l1svc(cat, op, arg, out)</code>，<code>cap = core_syscall_arg5()</code>（r8 槽位），实现于 <code>svc_sysapi_syscall.c</code>：</p><ul><li><code>out == 0 &amp;&amp; cap == 0</code> 是 OCIRE 发后即忘的拼写 -&gt; 渲染进一个 256 字节内核暂存缓冲，跳过拷回。</li><li><code>cap</code> 必须为 1..32768（WP06g2 中从 8192 上调，以便双语注册表 清单装得下）；<code>out</code> 由 <code>valid_user_ptr</code> 校验。</li><li><code>arg</code> 被拷进 256 字节内核缓冲——<strong>唯 cat OCIRE（18）例外，它得到 专用的 4096 字节栈缓冲</strong>，用于日志代理的追加。</li><li>分派之前：<code>sti</code> ... <code>svc_framework_dispatch(...)</code> ... <code>cli</code>—— op 体内的设备等待循环是节拍驱动的，不是死自旋。</li><li>服务的非零退出状态仍算成功调用；只有无法路由的类别/op（或 rc&lt;0 且 out 为空）才返回 -1。其余情况把 NUL 终止的文本拷回并返回 0。</li></ul><p>路由按类别字符串对照 <code>.oc_svcs</code> 表（链接段注册表——见 <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>）。<strong>20 个类别、208 个 op</strong>，编号只增不改，经 <code>tools/gen_l1svc_ops.py</code> 逐字节镜像进 ring 3：</p><table tabindex="0"><thead><tr><th>Cat</th><th>名称</th><th>目录</th><th>Ops</th><th>Cat</th><th>名称</th><th>目录</th><th>Ops</th></tr></thead><tbody><tr><td>1</td><td>time</td><td>services/time</td><td>4</td><td>11</td><td>watchdog</td><td>services/watchdog</td><td>1</td></tr><tr><td>2</td><td>block</td><td>services/block</td><td>23</td><td>12</td><td>crypto</td><td>services/crypto</td><td>2</td></tr><tr><td>3</td><td>nic</td><td>services/net</td><td>20</td><td>13</td><td>l1</td><td>services/l1</td><td>3</td></tr><tr><td>4</td><td>snd</td><td>services/audio</td><td>17</td><td>14</td><td>display</td><td>services/display</td><td>17</td></tr><tr><td>5</td><td>power</td><td>services/power</td><td>8</td><td>15</td><td>input</td><td>services/display</td><td>2</td></tr><tr><td>6</td><td>ota</td><td>services/selfhost</td><td>16</td><td>16</td><td>camera</td><td>services/camera</td><td>10</td></tr><tr><td>7</td><td>fs</td><td>services/fs</td><td>6</td><td>17</td><td>usb</td><td>services/usb</td><td>9</td></tr><tr><td>8</td><td>net</td><td>services/net</td><td>14</td><td>18</td><td>ocire</td><td>services/ocembed</td><td>2</td></tr><tr><td>9</td><td>health</td><td>services/health</td><td>3</td><td>19</td><td>diag</td><td>services/diag</td><td>39</td></tr><tr><td>10</td><td>klog</td><td>services/klog</td><td>3</td><td>20</td><td>tui</td><td>services/tui</td><td>9</td></tr></tbody></table><p>Cat 18 是仅限守卫的 OCIRE 通道（op 4 LOG_APPEND / 5 KLOG_SNAPSHOT）——针对 <code>ocire/agent/ocire_agent.c</code> 的冻结 ABI， 对一切非守护调用者拒绝（见 <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>）。</p><h2 id="输出捕获——旧命令体为何仍然可用" tabindex="-1">输出捕获——旧命令体为何仍然可用 <a class="header-anchor" href="#输出捕获——旧命令体为何仍然可用" aria-label="Permalink to &quot;输出捕获——旧命令体为何仍然可用&quot;">​</a></h2><p>多数 op 体是 v1/v2.2.0 时代经 <code>screen_console_puts</code> 打印的 shell 命令体。为了让它们经 L1SVC 服务，分派把它们包进 <code>core_kcap_run_fn(fn, arg, out, cap)</code>（<code>ocos/kernel/core_kcap.c</code>）： 捕获激活期间，<strong>捕获钩子即控制台钩子</strong>（控制台驱动恰好持有一个 钩子槽位），把字符收进调用者缓冲，同时抑制帧缓冲绘制与串口分岔。 捕获可叠至 4 层；只有最内层的活跃捕获接受数据；基础钩子（串口 编码器分岔）在最后一次捕获结束时重新装回；溢出被标记，绝不静默 截断。</p><p>每个 op 有三种路由风格（文档见各 l1 文件）：</p><ol><li><strong>捕获</strong>——一次性文本 op（大多数）。</li><li><strong>直通</strong>——<code>out[0]=0; return fn(arg);</code>，用于实时控制台会话： <code>sshd</code>、全部 9 个 TUI op（<a href="./tui-engine.html">tui-engine.md</a>）、 <code>ime -i</code> 与 <code>power sleep</code>（被捕获的多秒驻留会吞掉其间打印的 每一行控制台输出——监督引导期间实测发现）。</li><li><strong>缓冲渲染</strong>——服务用自己的 <code>put()</code> 辅助直接写进 <code>out</code> （<code>l1</code>、<code>klog</code>、<code>health</code>、<code>diag</code>、<code>fs</code>、<code>time</code>、<code>watchdog</code> 分派器）。</li></ol><h2 id="进程、elf-与-ring-3-世界" tabindex="-1">进程、ELF 与 ring 3 世界 <a class="header-anchor" href="#进程、elf-与-ring-3-世界" aria-label="Permalink to &quot;进程、ELF 与 ring 3 世界&quot;">​</a></h2><ul><li><strong>入口</strong>：<code>execve</code> 留下 <code>[rsp]=argc, [rsp+8]=argv</code>；每个应用 链接 <code>ocos/interface/crt0.asm</code>，由它安全读取并调用 <code>app_main(argc, argv)</code>，经 <code>SYS_EXIT2</code> 退出。</li><li><strong>ELF 装载</strong>：静态 ET_EXEC 与 ET_DYN（PIE）带 ASLR，外加动态 路径——PT_INTERP 探测、ld.so 映射于 0x10000000、由用户态 ld.so 完成 <code>.dynamic</code>/GOT/PLT 重定位、DT_NEEDED 对照内嵌 solib 表解析 （见 <a href="./../l1/solib-loader.html">../l1/solib-loader.md</a>）。</li><li><strong>程序注册表</strong>：<code>core_userprog_lookup(name, &amp;size)</code> 找到 284 个 gzip 内嵌程序之一（见 <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>）；<code>SYS_EXECVE</code> 在 首次使用时解压。</li><li><strong>信号</strong>：SIGHUP 1、SIGINT 2、SIGQUIT 3、SIGKILL 9、SIGUSR1 10、 SIGSEGV 11、SIGUSR2 12、SIGTERM 15、SIGCHLD 17、NSIG 32；在 系统调用返回时挂起投递；ring 3 异常的 SIGSEGV 投递带 3 次乒乓 守卫，随后击杀（见 <a href="./interrupts.html">interrupts.md</a>）。</li><li><strong>管道</strong>（内核侧）：32 个管道、4096 字节缓冲、fd 种类记录于 <code>user_proc_t.fds[]</code>（0=空闲、1=VFS fd、2=管道读、3=管道写）、 每端等待队列；<code>pipe_close_fd</code> 为统一收割器导出。</li><li><strong>mmap</strong>：每进程匿名递增分配器，位于 [0x3C000000, 0x3FFF0000)， 带 16 区域所有权表——没有共享内存系统调用；fork 是急切拷贝 （<code>VMM_FLAG_COW</code> 已定义但未使用）。</li><li><strong>作业控制</strong>（services/ipc）：<code>job_create</code> 拉起指定内嵌程序并把 作业绑定到真实 pid（不做“最高存活 pid”式猜测——BUG-0249）； <code>job_control</code> 0=前台等待、1=后台、2=经统一收割器击杀。</li></ul><p>以上全部内容的 L1 开发者视图： <a href="./../l1/overview.html">../l1/overview.md</a> 与 <a href="./../l1/surface-map.html">../l1/surface-map.md</a>。</p>`,24)])])}const h=d(r,[["render",s]]);export{_ as __pageData,h as default};
